// ★ v1.17.6: BollyFlix-এর নিজস্ব প্রক্সি-বেঞ্চ (ইউজার: "proxy pool thik moto kaj korche na").
//   সমস্যা: পুল-স্বাস্থ্য মাপা হত **ভিডি-সাইট** (VIDY_REFERER) দিয়ে; কিন্তু BollyFlix-এর আসল হপ
//   `dl.fastdlserver.site` — অনেক প্রক্সি Google/সাইটে যায়, অথচ gdflix-এ **403** (IP-flagged) বা
//   CONNECT-ই করে না ⇒ fid-রিজলভ সময়সীমার ভেতরেই মরে ⇒ কার্ড হারায়/ভাঙে।
//   সমাধান: আসল হপে-প্রমাণিত আলাদা বেঞ্চ (PX_BF) + ব্যর্থ-তালিকা (PX_BF_BAD) + রিয়েল-id দিয়ে ঢেউ।
const PX_BF = new Set();      // প্রক্সি → BollyFlix-হপে ৩০২/২০০ প্রমাণিত
const PX_BF_BAD = new Map();  // px → ts (403/ব্যর্থ ⇒ ১০ মিনিট বাদ)
let BF_BENCH_URL = '';        // শেষ সফল রিজলভের আসল `?id=` URL (বেঞ্চ-টার্গেট)
let bfBenchBusy = false, BFCHK = 0, bfBenchCursor = 0;
function pxHttpGet(px, url, timeoutMs = 6000) { // CONNECT-টানেল + TLS দিয়ে এক-কল, শুধু status ফেরে
  return new Promise(resolve => {
    let done = false, sock = null, tl = null;
    const fin = o => { if (done) return; done = true; clearTimeout(hm); try { if (tl) tl.destroy(); } catch { } try { if (sock) sock.destroy(); } catch { } resolve(o); };
    const t0 = Date.now();
    const hm = setTimeout(() => fin({ st: 0, err: 'timeout' }), timeoutMs);
    try {
      const u = new URL(url);
      const ci = px.indexOf(':');
      const phost = px.slice(0, ci), pport = Number(px.slice(ci + 1)) || 8080;
      sock = net.connect({ host: phost, port: pport });
      sock.once('error', e => fin({ st: 0, err: e.code || 'sock' }));
      sock.once('connect', () => sock.write('CONNECT ' + u.host + ':443 HTTP/1.1\r\nHost: ' + u.host + ':443\r\n\r\n'));
      let buf = Buffer.alloc(0);
      const onD = d => {
        buf = Buffer.concat([buf, d]);
        const i = buf.indexOf('\r\n\r\n');
        if (i < 0) return;
        sock.removeListener('data', onD);
        const head = buf.slice(0, i).toString('latin1');
        if (!/^HTTP\/1\.[01] 200/.test(head)) return fin({ st: 0, err: 'refused' });
        try {
          tl = tls.connect({ socket: sock, servername: u.hostname, rejectUnauthorized: false }, () => {
            tl.write('GET ' + (u.pathname + u.search) + ' HTTP/1.1\r\nHost: ' + u.hostname +
              '\r\nUser-Agent: ' + UA + '\r\nAccept: */*\r\nConnection: close\r\n\r\n');
          });
          let txt = '';
          tl.on('data', d2 => { if (txt.length < 1200) txt += d2.toString('latin1'); });
          tl.on('close', () => {
            const st = parseInt(((txt.split('\r\n')[0] || '').split(' ')[1]) || '0', 10);
            fin({ st, ms: Date.now() - t0 });
          });
          tl.once('error', e => fin({ st: 0, err: e.code || 'tls' }));
        } catch (e2) { fin({ st: 0, err: 'tls-init' }); }
      };
      sock.on('data', onD);
    } catch (e) { fin({ st: 0, err: 'init' }); }
  });
}
async function bfBenchWave() {
  if (bfBenchBusy || !POOL.length || Date.now() < MMR_ACTIVE_UNTIL) return;
  bfBenchBusy = true;
  try {
    BFCHK++;
    const tgt = BF_BENCH_URL || 'https://dl.fastdlserver.site/';
    const now = Date.now();
    const cands = POOL.map(c => c.px).filter(px => (PX_BF_BAD.get(px) || 0) <= now)
      .sort((a, b) => (PX_BF.has(a) ? 1 : 0) - (PX_BF.has(b) ? 1 : 0)); // নতুনগুলো আগে
    if (!cands.length) return;
    const width = Math.min(40, cands.length);
    const batch = [];
    for (let k = 0; k < width; k++) batch.push(cands[(bfBenchCursor + k) % cands.length]);
    bfBenchCursor = (bfBenchCursor + width) % cands.length;
    let ok = 0, bad = 0;
    await Promise.all(batch.map(async px => {
      const r = await pxHttpGet(px, tgt, 6500);
      const good = (r.st >= 200 && r.st < 400) || r.st === 404; // 302=আসল পথ, 200/404=হোস্টে-পৌঁছেছে
      if (good) { PX_BF.add(px); PX_BF_BAD.delete(px); pxRec(px, true, r.ms || 3000); ok++; }
      else { // 403 = gdflix-এ IP-flagged; timeout/refused = অচল — দুটোই BF-এর জন্য অচল
        PX_BF.delete(px);
        PX_BF_BAD.set(px, Date.now() + (r.st === 403 ? 20 * 60 * 1000 : 6 * 60 * 1000));
        bad++;
      }
    }));
    if (DBG && (BFCHK % 8 === 1)) console.error('[bfbench] wave=' + batch.length + ' ok=' + ok + ' bad=' + bad + ' pxbf=' + PX_BF.size + ' pool=' + POOL.length);
  } finally { bfBenchBusy = false; }
}
function bfBenchStart() {
  const loop = () => { setTimeout(() => { Promise.resolve(bfBenchWave()).catch(() => { }).finally(loop); }, 9000); };
  loop();
}


