// ★ SeekHead যাচাই + ঠিক করা (ক্যাশ-সহ)
async function bfSeekFix(cleanUrl, meta) {
  const e = bfCacheGet(BF_SEEKFIX, cleanUrl, 6 * 3600 * 1000);
  if (e) return e.fix || null;
  let fix = null;
  try {
    const rawSize = meta.rawSize;
    const head = await bfRawRange(cleanUrl, meta, 0, Math.min(65535, rawSize - 1));
    if (head && head.length > 64) {
      const hp = bfParseHead(head);
      if (hp && hp.cues && hp.cues.off >= 0 && hp.cues.len >= 1 && hp.cues.len <= 8) {
        // (ক) SeekHead-এর Cues-পয়েন্ট সত্যি কিনা — মাত্র ১৬ বাইট প্রোব
        const cuesAbs = hp.cues.val + hp.segStart;
        if (cuesAbs > 0 && cuesAbs + 16 <= rawSize) {
          const probe = await bfRawRange(cleanUrl, meta, cuesAbs, cuesAbs + 15);
          if (probe && probe.length >= 4 && probe[0] === 0x1c && probe[1] === 0x53 && probe[2] === 0xbb && probe[3] === 0x6b) {
            fix = { mode: 'ok', segStart: hp.segStart, cues: hp.cues, tags: hp.tags };
            if (DBG) console.error('[bf-seek] ok ' + String(cleanUrl).slice(-40) + ' cues@' + cuesAbs);
          }
        }
        // (খ) না হলে — আসল Cues খুঁজে SeekPosition ঠিক করো
        if (!fix) {
          const tl = Math.min(3 * 1024 * 1024, rawSize);
          const tail = await bfRawRange(cleanUrl, meta, rawSize - tl, rawSize - 1);
          if (tail && tail.length > 64) {
            const ts = bfScanTail(tail, rawSize - tl);
            if (ts.cuesAbs != null) {
              const cuesRel = ts.cuesAbs - hp.segStart;
              if (cuesRel >= 0 && cuesRel < Math.pow(2, 8 * hp.cues.len)) {
                fix = {
                  mode: 'rewrite', segStart: hp.segStart, cues: hp.cues, tags: hp.tags,
                  cuesRel, tagsRel: (ts.tagsAbs != null) ? ts.tagsAbs - hp.segStart : null
                };
                if (DBG) console.error('[bf-seek] rewrite ' + String(cleanUrl).slice(-40) + ' ' + hp.cues.val + '→' + cuesRel);
              }
            }
          }
        }
      }
    }
  } catch (err) { if (DBG) console.error('[bf-seek] ' + String(err && err.message).slice(0, 90)); }
  if (fix) bfCachePut(BF_SEEKFIX, cleanUrl, { fix }, 300);   // শুধু সফল ফল ক্যাশ হয়
  return fix;
}
