//   (byte-range ঠিক রাখার জন্য) আর UA-তে "ExoPlayerLib" থাকে; libmpv/mpv পাঠায় "gzip, deflate"।
function bfIsExoReq(req) {
  try {
    const ua = String((req.headers && req.headers['user-agent']) || '');
    if (/exoplayer|media3|exolib|exo-player/i.test(ua)) return true;
    // v1.17.5: UA-তে libmpv/mpv/vlc/ffmpeg থাকলে "identity" শুধু-লক্ষণ নয় (নইলে libmpv-ও 415 খেত)
    if (/libmpv|\bmpv\b|vlc|ffmpeg|ffplay|kodi|iina/i.test(ua)) return false;
    const ae = String((req.headers && req.headers['accept-encoding']) || '').trim().toLowerCase();
    // ExoPlayer/Media3 byte-range ঠিক রাখতে "identity" পাঠায়; libmpv/mpv পাঠায় "gzip, deflate"
    if (/(^|[\s,])identity([\s,]|$)/.test(ae)) return true;
  } catch { }
  return false;
}

